<script>
(function() {
  const POPUP_DELAY_MS = 10000; // 10 seconds delay as requested

  const NEEDS = [
    'Car rental or fleet software',
    'Website design & development',
    'E-commerce build',
    'Mobile app',
    'Custom software or internal system',
    'SEO or digital marketing',
    'AI, data or cloud work',
    'Something else'
  ];

  const BUDGETS = [
    'Prefer not to say',
    'Under $2,000',
    '$2,000 - $10,000',
    '$10,000 - $50,000',
    '$50,000+',
    'Monthly retainer'
  ];

  const options = list => list.map(v => `<option value="${v}">${v}</option>`).join('');

  const ARROW = `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2"
    stroke-linecap="round" stroke-linejoin="round"><path d="M5 12h14M13 6l6 6-6 6"/></svg>`;

  const markup = `
    <div class="ed-top">
      <span class="ed-mono ed-dot">Usually booked within 2 working days</span>
      <h2>Book your slot</h2>
      <p class="ed-req">Fields marked <i>*</i> are required.</p>
    </div>

    <div class="ed-scroll">
      <div class="ed-sec">
        <span class="ed-mono ed-rule">Your details</span>
        <div class="ed-grid">
          <div class="ed-fld">
            <label for="ed-name">Full name <i>*</i></label>
            <input id="ed-name" type="text" autocomplete="name" placeholder="Your name">
            <span class="err">Enter your full name</span>
          </div>
          <div class="ed-fld">
            <label for="ed-company">Company</label>
            <input id="ed-company" type="text" autocomplete="organization" placeholder="Optional">
          </div>
          <div class="ed-fld">
            <label for="ed-email">Work email <i>*</i></label>
            <input id="ed-email" type="email" autocomplete="email" placeholder="you@company.com">
            <span class="err">Enter a valid work email</span>
          </div>
          <div class="ed-fld">
            <label for="ed-phone">WhatsApp number <i>*</i></label>
            <input id="ed-phone" type="tel" autocomplete="tel" placeholder="00000 00000">
            <span class="err">Enter your WhatsApp number</span>
          </div>
        </div>
      </div>

      <div class="ed-sec">
        <span class="ed-mono ed-rule">The project</span>
        <div class="ed-grid">
          <div class="ed-fld wide">
            <label for="ed-need">What do you need? <i>*</i></label>
            <select id="ed-need">
              <option value="">Choose one</option>
              ${options(NEEDS)}
            </select>
            <span class="err">Pick the closest match</span>
          </div>
          <div class="ed-fld wide">
            <label for="ed-budget">Budget range</label>
            <select id="ed-budget">${options(BUDGETS)}</select>
            <span class="hint">A range helps us bring the right person to the call. It isn't a commitment.</span>
          </div>
          <div class="ed-fld wide">
            <label for="ed-brief">Tell us about the project <i>*</i></label>
            <textarea id="ed-brief" placeholder="A paragraph is enough. Links to anything relevant help."></textarea>
            <span class="err">A sentence or two, so we can prepare</span>
          </div>
        </div>
      </div>

      <div class="ed-sec">
        <span class="ed-mono ed-rule">Verification</span>
        <div style="background:#f8fafc; border:1px solid #e2e8f0; border-radius:12px; padding:16px;">
          <div style="display:flex; align-items:center; justify-content:space-between; gap:12px; flex-wrap:wrap;">
            <div style="background:#ffffff; padding:6px 12px; border-radius:8px; border:1px solid #cbd5e1; display:inline-flex; align-items:center;">
              <span id="popup-captcha-img">{!! captcha_img() !!}</span>
            </div>
            <button type="button" id="popupReloadCaptcha" style="display:inline-flex; align-items:center; gap:8px; background:#ffffff; border:1px solid #cbd5e1; border-radius:8px; padding:8px 14px; font-size:13px; font-weight:600; color:#475569; cursor:pointer; transition:all 0.2s ease;">
              <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M21.5 2v6h-6M2.5 22v-6h6M2 11.5a10 10 0 0 1 18.8-4.3M22 12.5a10 10 0 0 1-18.8 4.2"/></svg>
              <span>Click to refresh code</span>
            </button>
          </div>
          <div class="ed-fld wide" style="margin-top:12px;">
            <label for="popup-captcha" style="font-size:11px; font-weight:700; letter-spacing:0.08em; text-transform:uppercase; color:#475569;">CAPTCHA <i>*</i></label>
            <input id="popup-captcha" type="text" placeholder="Enter Captcha Code" style="background:#ffffff; border:1px solid #cbd5e1; border-radius:8px; padding:10px 14px; font-size:14px; width:100%; color:#0f172a;">
            <span class="err">Enter the captcha code</span>
          </div>
        </div>
      </div>

      <div class="ed-sec">
        <span class="ed-mono ed-rule">Before we talk</span>
        <label class="ed-chk">
          <input id="ed-nda" type="checkbox">
          <span>I'd like an NDA in place before we talk in detail.</span>
        </label>
        <label class="ed-chk" id="ed-consent-row">
          <input id="ed-consent" type="checkbox">
          <span>I agree to Edion contacting me about this enquiry. See our
            <a href="{{ route('resources.privacy-policy') }}" target="_blank" rel="noopener">privacy policy</a>. <i>*</i></span>
        </label>
      </div>
    </div>

    <div class="ed-foot">
      <span>Prefer to call? <a href="tel:+919696787596">+91 96967 87596</a></span>
      <span>Mon–Sat · 10:00–20:00 IST</span>
    </div>
  `;

  const flag = (el, bad) => {
    const holder = el.closest('.ed-fld');
    if (holder) holder.classList.toggle('bad', bad);
  };

  let popupIti = null;

  function collect(){
    const $ = id => document.getElementById(id);
    const name = $('ed-name'), email = $('ed-email'), phone = $('ed-phone'),
          need = $('ed-need'), brief = $('ed-brief'), consent = $('ed-consent'),
          captcha = $('popup-captcha');

    if (!name || !email || !phone || !need || !brief || !consent || !captcha) return false;

    const checks = [
      [name,  name.value.trim().length >= 2],
      [email, /^[^\s@]+@[^\s@]+\.[a-z]{2,}$/i.test(email.value.trim())],
      [phone, phone.value.replace(/\D/g,'').length >= 6],
      [need,  need.value !== ''],
      [brief, brief.value.trim().length >= 10],
      [captcha, captcha.value.trim().length >= 1]
    ];
    checks.forEach(([el, ok]) => flag(el, !ok));

    document.getElementById('ed-consent-row').classList.toggle('bad', !consent.checked);

    const bad = checks.find(([, ok]) => !ok);
    if (bad){
      bad[0].focus();
      Swal.showValidationMessage('Check the marked fields');
      return false;
    }
    if (!consent.checked){
      consent.focus();
      Swal.showValidationMessage('Tick the consent box so we can reply');
      return false;
    }

    let fullPhone = phone.value.trim();
    if (popupIti) {
      const countryData = popupIti.getSelectedCountryData();
      const rawDigits = phone.value.trim().replace(/^\+/, '');
      let itiNum = popupIti.getNumber();
      if (!itiNum || !itiNum.startsWith('+')) {
        const dialCode = countryData && countryData.dialCode ? ('+' + countryData.dialCode) : '';
        if (dialCode && rawDigits) {
          fullPhone = rawDigits.startsWith(countryData.dialCode) ? ('+' + rawDigits) : (dialCode + ' ' + rawDigits);
        } else {
          fullPhone = rawDigits;
        }
      } else {
        fullPhone = itiNum;
      }
    }

    return {
      name:    name.value.trim(),
      company: $('ed-company').value.trim(),
      email:   email.value.trim(),
      phone:   fullPhone,
      need:    need.value,
      budget:  $('ed-budget').value,
      brief:   brief.value.trim(),
      nda:     $('ed-nda').checked,
      captcha: captcha.value.trim()
    };
  }

  let popupFired = false;

  window.openEdionConsultationPopup = function() {
    if (Swal.isVisible()) return;
    popupFired = true;

    try {
      sessionStorage.setItem('edion_consultation_popup_shown', 'true');
      localStorage.setItem('edion_consultation_popup_last', Date.now());
    } catch(e){}

    Swal.fire({
      html: markup,
      width: 700,
      padding: 0,
      showCloseButton: true,
      showCancelButton: true,
      showDenyButton: false,
      buttonsStyling: false,
      focusConfirm: false,
      allowOutsideClick: false,
      confirmButtonText: `<span style="display:inline-flex;align-items:center;gap:8px;white-space:nowrap;">Request my consultation ${ARROW}</span>`,
      cancelButtonText: 'Not right now',
      customClass: {
        container: 'ed-wrap',
        popup: 'ed-card',
        confirmButton: 'ed-pill ed-send',
        cancelButton: 'ed-pill ghost ed-skip'
      },
      didOpen: () => {
        const nameEl = document.getElementById('ed-name');
        if (nameEl) nameEl.focus();
        document.querySelectorAll('.ed-scroll input, .ed-scroll select, .ed-scroll textarea')
          .forEach(el => el.addEventListener('input', () => flag(el, false)));
        const consentEl = document.getElementById('ed-consent');
        if (consentEl) {
          consentEl.addEventListener('change', e => {
            document.getElementById('ed-consent-row').classList.toggle('bad', !e.target.checked);
          });
        }

        const phoneEl = document.getElementById('ed-phone');
        if (phoneEl && window.intlTelInput) {
          popupIti = window.intlTelInput(phoneEl, {
            preferredCountries: ["in", "ae", "sa", "us", "gb", "qa", "om", "kw", "bh", "jo", "ca", "au"],
            initialCountry: "in",
            showSelectedDialCode: true,
            countrySearch: true,
            autoPlaceholder: "polite",
            placeholderNumberType: "MOBILE",
            customPlaceholder: function(selectedCountryPlaceholder, selectedCountryData) {
              return selectedCountryPlaceholder ? selectedCountryPlaceholder.replace(/^\+?\d+\s*/, '') : "00000 00000";
            },
            utilsScript: "https://cdnjs.cloudflare.com/ajax/libs/intl-tel-input/19.2.16/js/utils.js"
          });

          fetch('https://ipapi.co/json/')
            .then(res => res.json())
            .then(data => {
              if (data && data.country_code && popupIti) {
                popupIti.setCountry(data.country_code.toLowerCase());
              }
            })
            .catch(() => {
              fetch('https://ip-api.com/json')
                .then(res => res.json())
                .then(data => {
                  if (data && data.countryCode && popupIti) {
                    popupIti.setCountry(data.countryCode.toLowerCase());
                  }
                })
                .catch(() => {});
            });

          phoneEl.addEventListener('input', function() {
            this.value = this.value.replace(/[^0-9\s]/g, '');
          });
        }

        const reloadBtn = document.getElementById('popupReloadCaptcha');
        if (reloadBtn) {
          reloadBtn.addEventListener('click', e => {
            e.preventDefault();
            fetch('{{ url("reload-captcha") }}')
              .then(res => res.json())
              .then(data => {
                const img = document.getElementById('popup-captcha-img');
                if (img) img.innerHTML = data.captcha;
              })
              .catch(err => console.error('Captcha refresh error:', err));
          });
        }
      },
      preConfirm: () => {
        Swal.resetValidationMessage();
        const data = collect();
        if (!data) return false;

        return fetch("{{ route('consultation.store') }}", {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'X-CSRF-TOKEN': '{{ csrf_token() }}',
            'X-Requested-With': 'XMLHttpRequest'
          },
          body: JSON.stringify({
            name: data.name,
            company: data.company,
            email: data.email,
            phone: data.phone,
            number: data.phone,
            interest: data.need,
            budget: data.budget,
            brief: data.brief,
            message: data.brief,
            nda: data.nda ? 1 : 0,
            captcha: data.captcha
          })
        })
        .then(res => {
          if (!res.ok) {
            fetch('{{ url("reload-captcha") }}')
              .then(r => r.json())
              .then(d => {
                const img = document.getElementById('popup-captcha-img');
                if (img) img.innerHTML = d.captcha;
                const inp = document.getElementById('popup-captcha');
                if (inp) inp.value = '';
              });

            return res.json().then(errData => {
              let errorMsg = 'Failed to submit request. Please try again.';
              if (errData.errors) {
                errorMsg = Object.values(errData.errors).flat().join('<br>');
              } else if (errData.message) {
                errorMsg = errData.message;
              }
              Swal.showValidationMessage(errorMsg);
              return false;
            });
          }
          return res.json();
        })
        .then(resData => {
          if (!resData || !resData.success) return false;
          return data;
        })
        .catch(err => {
          Swal.showValidationMessage('Failed to submit request. Please try again.');
          return false;
        });
      }
    }).then(r => {
      if (!r.isConfirmed || !r.value) return;

      const d = r.value;
      Swal.fire({
        html: `
          <div class="ed-done">
            <span class="ed-mono ed-dot ed-green">Request received</span>
            <h2>We'll confirm your slot.</h2>
            <p>Thanks, ${d.name.split(' ')[0]}. Before the call we'll look at your site, your
               competitors and your stack, so we don't spend the thirty minutes asking basics.</p>
            <dl>
              <dt>Reply to</dt><dd>${d.email}</dd>
              <dt>Topic</dt><dd>${d.need}</dd>
              <dt>NDA first</dt><dd>${d.nda ? 'Yes' : 'Not requested'}</dd>
            </dl>
          </div>`,
        width: 560,
        buttonsStyling: false,
        confirmButtonText: `Back to the site ${ARROW}`,
        customClass: { container:'ed-wrap', popup:'ed-card', confirmButton:'ed-pill ed-send' }
      });
    });
  };

  document.addEventListener('DOMContentLoaded', function() {
    const ONE_DAY_MS = 24 * 60 * 60 * 1000; // 24 hours cooldown
    let sessionShown = false;
    let isRecentlyShown = false;
    
    try {
      sessionShown = sessionStorage.getItem('edion_consultation_popup_shown') === 'true';
      const lastShown = parseInt(localStorage.getItem('edion_consultation_popup_last') || '0', 10);
      if (lastShown && (Date.now() - lastShown) < ONE_DAY_MS) {
        isRecentlyShown = true;
      }
    } catch(e){}

    const isConsultationPage = window.location.pathname.includes('free-consultation');

    // Show popup only ONCE in the whole site after 10s (not shown again until session reset or 24h)
    if (!sessionShown && !isRecentlyShown && !isConsultationPage) {
      setTimeout(function() {
        if (!popupFired && !window.location.pathname.includes('free-consultation')) {
          window.openEdionConsultationPopup();
        }
      }, POPUP_DELAY_MS);
    }
  });
})();
</script>
</body>
@stack('scripts')

